  const empresaId = getEmpresaIdSafe3(c);
  const periodo = await db.prepare(
    `SELECT
         ff.id,
         ff.funcionario_id,
         ff.tipo,
         ff.data_inicio,
         ff.data_fim,
         ff.escala_alocacao_id
       FROM funcionario_ferias ff
       JOIN funcionarios f ON f.id = ff.funcionario_id AND f.deleted_at IS NULL
       WHERE ff.id = ?
         AND ff.funcionario_id = ?
         AND ff.deleted_at IS NULL
         AND (? IS NULL OR f.empresa_id IS NULL OR f.empresa_id = ?)
       LIMIT 1`
  ).bind(feriasId, funcionarioId, empresaId ?? null, empresaId ?? null).first();
  if (!periodo) {
    return c.json({ success: false, error: "Per\xEDodo n\xE3o encontrado" }, 404);
  }
  if (periodo.escala_alocacao_id) {
    return c.json(
      {
        success: false,
        error: "Este per\xEDodo foi gerado a partir de uma situa\xE7\xE3o da escala. Remova a situa\xE7\xE3o na escala correspondente."
      },
      409
    );
  }
