    const nomeArquivo = funcionario2 ? `Certificados-${funcionario2.matricula}-${funcionario2.nome.replace(/\s+/g, "_")}.zip` : `Certificados-Funcionario-${funcionarioId}.zip`;
    return new Response(zipped, {
      headers: {
        "Content-Type": "application/zip",
        "Content-Disposition": `attachment; filename="${nomeArquivo}"`,
        "Content-Length": zipped.byteLength.toString()
      }
    });
