app19.post("/:id/upload", auth(), async (c) => {
  try {
    const db = c.env.DB;
    const bucket = c.env.BUCKET;
    const funcionarioId = parseInt(c.req.param("id"));
    if (isNaN(funcionarioId)) return jsonError(c, "ID inv\xE1lido", 400, "ID_INVALIDO");
    const contentType = c.req.header("Content-Type") || "";
    if (!contentType.toLowerCase().includes("multipart/form-data")) {
      return jsonError(
        c,
        "Content-Type multipart/form-data obrigat\xF3rio",
        400,
        "CONTENT_TYPE_INVALIDO"
      );
    }
    const formData = await c.req.formData();
    const file = formData.get("file");
    if (!file) return jsonError(c, "Arquivo n\xE3o enviado", 400, "ARQUIVO_OBRIGATORIO");
    if (file.size > 1e7)
      return jsonError(c, "Arquivo excede limite de 10MB", 422, "ARQUIVO_GRANDE");
    if (!file.name.toLowerCase().endsWith(".pdf"))
      return jsonError(c, "Somente PDF \xE9 permitido", 422, "ARQUIVO_INVALIDO");
    const uuid5 = crypto.randomUUID();
    const r2Key = `funcionarios/${funcionarioId}/${uuid5}.pdf`;
    const buf = await file.arrayBuffer();
    const uint8 = new Uint8Array(buf);
    const hashBuffer = await crypto.subtle.digest("SHA-256", uint8);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    const hashHex = hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
    await bucket.put(r2Key, uint8, { httpMetadata: { contentType: "application/pdf" } });
    let insertResult;
    try {
      insertResult = await db.prepare(
        `INSERT INTO documentos (uuid, funcionario_id, nome_arquivo, tipo, tamanho, r2_key, sha256_hash, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))`
      ).bind(uuid5, funcionarioId, file.name, "application/pdf", file.size, r2Key, hashHex).run();
    } catch (insertError) {
      const errorMsg = String(insertError);
      if (errorMsg.includes("no column named sha256_hash")) {
        console.warn(
          "[pasta-virtual/:id/upload] Coluna sha256_hash n\xE3o existe, inserindo sem hash"
        );
        insertResult = await db.prepare(
          `INSERT INTO documentos (uuid, funcionario_id, nome_arquivo, tipo, tamanho, r2_key, created_at, updated_at)
             VALUES (?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))`
        ).bind(uuid5, funcionarioId, file.name, "application/pdf", file.size, r2Key).run();
      } else {
        throw insertError;
      }
    }
    return jsonOk(
      c,
      { id: insertResult.meta.last_row_id, uuid: uuid5, r2_key: r2Key },
      "Upload realizado com sucesso"
    );
  } catch (e) {
    const err2 = e;
    return jsonError(c, err2.message || "Falha ao fazer upload", err2.status || 500, err2.code);
  }
});
