app20.get("/stream/:id", auth(), async (c) => {
  const db = c.env.DB;
  const bucket = c.env.BUCKET;
  const id = parseInt(c.req.param("id"));
  if (isNaN(id)) {
    badRequest("ID inv\xE1lido");
  }
  const documento = await db.prepare("SELECT * FROM documentos WHERE id = ? AND deleted_at IS NULL").bind(id).first();
  if (!documento) {
    notFound("Documento n\xE3o encontrado");
  }
  try {
    const object = await bucket.get(documento.r2_key);
    if (!object) {
      notFound("Arquivo n\xE3o encontrado no R2");
    }
    let fileBuffer;
    if (object.body instanceof ReadableStream) {
      const reader = object.body.getReader();
      const chunks = [];
      let result = await reader.read();
      while (!result.done) {
        chunks.push(result.value);
        result = await reader.read();
      }
      const totalLength = chunks.reduce((acc, chunk) => acc + chunk.length, 0);
      const combined = new Uint8Array(totalLength);
      let offset = 0;
      for (const chunk of chunks) {
        combined.set(chunk, offset);
        offset += chunk.length;
      }
      fileBuffer = combined;
    } else {
      fileBuffer = new Uint8Array(await object.arrayBuffer());
    }
    const contentType = documento.tipo || "application/octet-stream";
    const isPdf = contentType.toLowerCase().includes("pdf");
    const safeFileName = String(documento.nome_arquivo || "arquivo").replace(/"/g, "");
    const encodedFileName = encodeURIComponent(safeFileName);
    const origin = c.req.header("Origin");
    const resolvedOrigin = resolveAllowedOrigin(origin, c.env.CORS_ORIGINS);
    return new Response(fileBuffer, {
      headers: {
        "Content-Type": contentType,
        "Content-Disposition": `${isPdf ? "inline" : "attachment"}; filename="${safeFileName}"; filename*=UTF-8''${encodedFileName}`,
        "Content-Length": fileBuffer.byteLength.toString(),
        "Cache-Control": "private, max-age=3600",
        "Access-Control-Allow-Origin": resolvedOrigin,
        "Access-Control-Allow-Credentials": "true",
        "Access-Control-Expose-Headers": "Content-Disposition, Content-Length, Content-Type",
        Vary: "Origin"
      }
    });
  } catch (error4) {
    console.error("Erro no streaming:", error4);
    return c.json({ success: false, error: "Erro ao baixar arquivo" }, 500);
  }
});
