app21.get("/queue", auth(), requireRole2("admin", "manager"), async (c) => {
  const db = c.env.DB;
  const limit = Math.min(parseInt(c.req.query("limit") || "200"), 500);
  const offset = Math.max(parseInt(c.req.query("offset") || "0"), 0);
  const search = (c.req.query("search") || "").trim().toLowerCase();
  const baseSql = `SELECT 
      q.id,
      q.historico_id,
      q.current_codigo,
      q.target_tipo_id,
      q.status,
      q.reason,
      q.created_at,
      q.updated_at,
      h.funcionario_id,
      f.nome AS funcionario_nome,
      h.data_conclusao,
      h.data_vencimento,
      h.numero_certificado
    FROM qualificacoes_historico_reclass_queue q
    JOIN qualificacoes_historico h ON h.id = q.historico_id
    LEFT JOIN funcionarios f ON f.id = h.funcionario_id
    WHERE q.status = 'PENDING'
      AND h.deleted_at IS NULL
      AND (f.deleted_at IS NULL OR f.deleted_at IS NULL)`;
  let finalSql = baseSql + " ORDER BY h.data_conclusao DESC LIMIT ? OFFSET ?";
  let bindings = [limit, offset];
  if (search) {
    finalSql = baseSql + " AND (LOWER(f.nome) LIKE ? OR CAST(h.funcionario_id AS TEXT) LIKE ?) ORDER BY h.data_conclusao DESC LIMIT ? OFFSET ?";
    bindings = [`%${search}%`, `%${search}%`, limit, offset];
  }
  const { results } = await db.prepare(finalSql).bind(...bindings).all();
  const countRow = await db.prepare(
    "SELECT COUNT(*) as total FROM qualificacoes_historico_reclass_queue WHERE status='PENDING'"
  ).first();
  const response = {
    success: true,
    data: { items: results || [], total: countRow?.total || 0 }
  };
  return c.json(response);
});
