app22.post(
  "/historico/:id/certificados/upload",
  auth(),
  requireRole2("admin", "manager"),
  async (c) => {
    const db = c.env.DB;
    const bucket = c.env.BUCKET;
    const id = parseInt(c.req.param("id"));
    if (isNaN(id)) {
      return c.json({ success: false, error: "ID inv\xE1lido" }, 400);
    }
    try {
      const { historico, nomeFuncionario, cpf, codigo } = await resolveCertificadoContext(db, id);
      const storageColumns = await getCertificadosStorageColumns(db);
      const empresaId = getEmpresaId(c);
      await backfillCertificadoAtualNaPastaVirtual(db, storageColumns, {
        historicoId: id,
        funcionarioId: historico.funcionario_id,
        certificadoArquivoId: historico.certificado_arquivo_id ?? null,
        empresaId
      });
      const form = await c.req.formData();
      const file = form.get("file");
      const descricao = form.get("descricao") || null;
      const dataRealizacaoStr = form.get("data_realizacao") || null;
      if (!file) {
        return c.json({ success: false, error: 'Campo "file" \xE9 obrigat\xF3rio' }, 400);
      }
      const MAX_SIZE = 10 * 1024 * 1024;
      if (file.size > MAX_SIZE) {
        return c.json(
          {
            success: false,
            error: `Arquivo muito grande. M\xE1ximo: 10MB (enviado: ${(file.size / 1024 / 1024).toFixed(2)}MB)`
          },
          400
        );
      }
      if (file.size < 1024) {
        return c.json({ success: false, error: "Arquivo muito pequeno (m\xEDnimo: 1KB)" }, 400);
      }
      const arrayBuffer = await file.arrayBuffer();
      const header = new Uint8Array(arrayBuffer.slice(0, 5));
      const isPDF = header[0] === 37 && // %
      header[1] === 80 && // P
      header[2] === 68 && // D
      header[3] === 70 && // F
      header[4] === 45;
      if (!isPDF) {
        return c.json(
          {
            success: false,
            error: "Arquivo inv\xE1lido. N\xE3o \xE9 um PDF real (magic bytes inv\xE1lidos)"
          },
          400
        );
      }
      let dataRealiza\u00E7\u00E3o;
      if (dataRealizacaoStr) {
        dataRealiza\u00E7\u00E3o = new Date(dataRealizacaoStr);
      } else if (historico.data_conclusao) {
        dataRealiza\u00E7\u00E3o = new Date(historico.data_conclusao);
      } else if (historico.data_vencimento) {
        dataRealiza\u00E7\u00E3o = new Date(historico.data_vencimento);
      } else {
        return c.json(
          {
            success: false,
            error: "Imposs\xEDvel fazer upload: qualifica\xE7\xE3o n\xE3o possui data de conclus\xE3o ou vencimento."
          },
          400
        );
      }
      const uuid5 = crypto.randomUUID().substring(0, 8);
      const nomeArquivo = gerarNomeArquivoPadronizado({
        tipo: "CERTIFICADO_QUALIFICACAO",
        nomeFuncionario,
        cpf,
        data: dataRealiza\u00E7\u00E3o,
        codigo,
        uuid: uuid5
      });
      console.log("[UPLOAD CERT] Gerando certificado:", {
        historicoId: id,
        cpf,
        codigo,
        nomeArquivoGerado: nomeArquivo
      });
      const r2Key = `certificados/${nomeArquivo}`;
      const uint8Array = new Uint8Array(arrayBuffer);
      const fileType = file.type || "application/pdf";
      const hashBuffer = await crypto.subtle.digest("SHA-256", uint8Array);
      const hashArray = Array.from(new Uint8Array(hashBuffer));
      const hash = hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
      await bucket.put(r2Key, uint8Array, {
        httpMetadata: {
          contentType: fileType
        },
        customMetadata: {
          tipo: "CERTIFICADO_QUALIFICACAO",
          cpf,
          codigo,
          historico_id: String(historico.id),
          data_referencia: dataRealiza\u00E7\u00E3o.toISOString(),
          origem: "upload_manual",
          hash_sha256: hash
        }
      });
      const result = await db.prepare(
        storageColumns.documentosHasEmpresaId ? `INSERT INTO documentos (
                 uuid, funcionario_id, nome_arquivo, tipo, tamanho, r2_key,
                 descricao, empresa_id, created_at, updated_at
               ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))` : `INSERT INTO documentos (
                 uuid, funcionario_id, nome_arquivo, tipo, tamanho, r2_key,
                 descricao, created_at, updated_at
               ) VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))`
      ).bind(
        ...storageColumns.documentosHasEmpresaId ? [
          uuid5,
          historico.funcionario_id,
          nomeArquivo,
          fileType,
          uint8Array.byteLength,
          r2Key,
          descricao || `Certificado anexado para qualifica\xE7\xE3o ${codigo} em ${dataRealiza\u00E7\u00E3o.toISOString().split("T")[0]}`,
          empresaId
        ] : [
          uuid5,
          historico.funcionario_id,
          nomeArquivo,
          fileType,
          uint8Array.byteLength,
          r2Key,
          descricao || `Certificado anexado para qualifica\xE7\xE3o ${codigo} em ${dataRealiza\u00E7\u00E3o.toISOString().split("T")[0]}`
        ]
      ).run();
      const documentoId = result.meta.last_row_id;
      console.log(`\u2705 [UPLOAD CERT] Certificado salvo: ID ${documentoId}`);
      try {
        await insertCertificadoNaPastaVirtual(db, storageColumns, {
          funcionarioId: historico.funcionario_id,
          documentoId: Number(documentoId),
          historicoId: id,
          empresaId,
          r2Key,
          nomeArquivo,
          descricao: `Certificado ${codigo} - ${nomeFuncionario}`
        });
        console.log("\u2705 [UPLOAD CERT] Certificado inserido na pasta_virtual");
      } catch (e) {
        console.error("\u274C [UPLOAD CERT] Erro ao inserir na pasta_virtual:", e);
      }
      const numeroCertificado = nomeArquivo.replace(".pdf", "");
      await db.prepare(
        `UPDATE qualificacoes_historico
           SET certificado_arquivo_id = ?,
               arquivo_url = ?,
               numero_certificado = ?,
               updated_at = datetime('now')
           WHERE id = ?`
      ).bind(documentoId, `/api/pasta-virtual/stream/${documentoId}`, numeroCertificado, id).run();
      console.log(`\u2705 [UPLOAD CERT] Linked documento ${documentoId} to historico ${id}`);
      const ua2 = extrairUsuarioAuditoria(c);
      await registrarAuditoria({
        db,
        tabela: "documentos",
        acao: "INSERT",
        registro_id: documentoId,
        dados_novos: { historico_id: id, r2_key: r2Key, nome_arquivo: nomeArquivo },
        ...ua2
      });
      const response = {
        success: true,
        data: {
          id: documentoId,
          uuid: uuid5,
          r2_key: r2Key
        },
        message: "Certificado anexado com sucesso"
      };
      return c.json(response, 201);
    } catch (error4) {
      console.error("[UPLOAD CERT] Erro:", error4);
      return c.json(
        {
          success: false,
          error: "Erro ao fazer upload do certificado",
          details: error4 instanceof Error ? error4.message : "Erro desconhecido"
        },
        500
      );
    }
  }
);
