opsRouter.post("/recuperar-orfaos", auth(), requireRole2("admin"), async (c) => {
  const db = c.env.DB;
  try {
    console.log("\u{1F527} [RECUPERAR ORFAOS] Iniciando busca de certificados \xF3rf\xE3os...");
    const { results: orfaos } = await db.prepare(
      `
        SELECT
          d.id as documento_id,
          d.nome_arquivo,
          d.funcionario_id,
          d.created_at as documento_data,
          d.r2_key
        FROM documentos d
        WHERE d.deleted_at IS NULL
          AND d.nome_arquivo LIKE 'CERT-%'
          AND d.id NOT IN (
            SELECT certificado_arquivo_id FROM qualificacoes_historico
            WHERE certificado_arquivo_id IS NOT NULL AND deleted_at IS NULL
          )
        ORDER BY d.funcionario_id, d.created_at DESC
        `
    ).all();
    console.log(`\u{1F4CB} Encontrados ${orfaos?.length || 0} certificados \xF3rf\xE3os`);
    if (!orfaos || orfaos.length === 0) {
      return c.json({
        success: true,
        message: "Nenhum certificado \xF3rf\xE3o encontrado",
        data: { linkedCount: 0, orfaosCount: 0 }
      });
    }
    let linkedCount = 0;
    for (const orfao of orfaos) {
      try {
        const parts = orfao.nome_arquivo.split("-");
        if (parts.length < 3) {
          console.log(`\u26A0\uFE0F  Nome inv\xE1lido: ${orfao.nome_arquivo} (${parts.length} partes)`);
          continue;
        }
        const codigo = parts[2];
        console.log(
          `\u{1F50D} [RECUPERAR] Documento ${orfao.documento_id} (${orfao.nome_arquivo}) \u2192 buscando qual ${codigo}`
        );
        const { results: candidatos } = await db.prepare(
          `
            SELECT
              qh.id,
              qh.data_conclusao
            FROM qualificacoes_historico qh
            WHERE qh.funcionario_id = ?
              AND qh.codigo = ?
              AND qh.certificado_arquivo_id IS NULL
              AND qh.deleted_at IS NULL
            ORDER BY qh.id DESC
            LIMIT 1
            `
        ).bind(orfao.funcionario_id, codigo).all();
        if (!candidatos || candidatos.length === 0) {
          console.log(
            `\u26A0\uFE0F  Nenhuma qualifica\xE7\xE3o encontrada: func=${orfao.funcionario_id}, codigo=${codigo}`
          );
          continue;
        }
        const melhorCandidato = candidatos[0];
        console.log(
          `\u{1F4CC} [RECUPERAR] Linkando documento ${orfao.documento_id} \u2192 historico ${melhorCandidato.id}`
        );
        await db.prepare(
          `UPDATE qualificacoes_historico
             SET certificado_arquivo_id = ?, updated_at = datetime('now')
             WHERE id = ?`
        ).bind(orfao.documento_id, melhorCandidato.id).run();
        console.log(
          `\u2705 [RECUPERAR] Linked documento ${orfao.documento_id} \u2192 historico ${melhorCandidato.id}`
        );
        linkedCount++;
      } catch (e) {
        console.error(
          `\u274C Erro ao linkar documento ${orfao.documento_id}:`,
          e instanceof Error ? e.message : e
        );
      }
    }
    console.log(`\u2705 [RECUPERAR ORFAOS] Recuperados ${linkedCount} certificados`);
    return c.json({
      success: true,
      message: `Recuperados ${linkedCount} certificados`,
      data: {
        linkedCount,
        orfaosCount: orfaos.length,
        remainingOrfaos: orfaos.length - linkedCount
      }
    });
  } catch (error4) {
    console.error("\u274C [RECUPERAR ORFAOS] Erro:", error4);
    return c.json(
      {
        success: false,
        error: "Erro ao recuperar certificados",
        details: error4 instanceof Error ? error4.message : "Erro desconhecido"
      },
      500
    );
  }
});
