async function getTaxaConclusaoMensal(db) {
  try {
    const results = await db.prepare(
      `SELECT
           strftime('%Y-%m', data) as mes,
           COUNT(CASE WHEN status = 'CONCLUIDO' THEN 1 END) * 100.0 / 
           NULLIF(COUNT(*), 0) as taxa
         FROM simulador_agendamentos
         WHERE deleted_at IS NULL
         AND data >= date('now', '-6 months')
         GROUP BY strftime('%Y-%m', data)
         ORDER BY mes ASC`
    ).all();
    const meses = [];
    const taxas = [];
    (results.results || []).forEach((row) => {
      const mesRaw = String(row.mes || "");
      const [, mes] = mesRaw.split("-");
      const mesesNomes = [
        "Jan",
        "Fev",
        "Mar",
        "Abr",
        "Mai",
        "Jun",
        "Jul",
        "Ago",
        "Set",
        "Out",
        "Nov",
        "Dez"
      ];
      meses.push(mesesNomes[parseInt(mes) - 1]);
      taxas.push(Math.round(Number(row.taxa || 0)));
    });
    return {
      meses,
      taxas,
      meta: 90
    };
  } catch (error4) {
    console.error("[DASHBOARD] Erro ao buscar taxa de conclus\xE3o mensal:", error4);
    return {
      meses: [],
      taxas: [],
      meta: 90
    };
  }
}
