async function getUtilizacaoSimuladores(db) {
  try {
    const results = await db.prepare(
      `SELECT
           s.id,
           s.nome,
           s.fabricante,
           s.modelo,
           COALESCE(SUM(CASE WHEN sa.status IN ('AGENDADO', 'CONCLUIDO') THEN sa.duracao_minutos END), 0) / 60.0 as horas_programadas,
           720 as horas_disponiveis,
           COALESCE(SUM(CASE WHEN sa.status IN ('AGENDADO', 'CONCLUIDO') THEN sa.duracao_minutos END), 0) * 100.0 / (720 * 60) as taxa_utilizacao,
           'operacional' as status
         FROM simuladores s
         LEFT JOIN simulador_agendamentos sa ON sa.simulador_id = s.id
           AND sa.deleted_at IS NULL
           AND sa.data >= date('now', '-30 days')
           AND sa.data <= date('now')
         WHERE s.deleted_at IS NULL
         GROUP BY s.id, s.nome, s.fabricante, s.modelo
         ORDER BY taxa_utilizacao DESC`
    ).all();
    const simuladores = (results.results || []).map((row) => ({
      id: Number(row.id || 0),
      nome: String(row.nome || ""),
      fabricante: String(row.fabricante || ""),
      modelo: String(row.modelo || ""),
      horasProgramadas: Math.round(Number(row.horas_programadas || 0)),
      horasDisponiveis: Number(row.horas_disponiveis || 0),
      taxaUtilizacao: Math.round(Number(row.taxa_utilizacao || 0)),
      status: row.status || "operacional"
    }));
    return { simuladores };
  } catch (error4) {
    console.error("[DASHBOARD] Erro ao buscar utiliza\xE7\xE3o de simuladores:", error4);
    return { simuladores: [] };
  }
}
