async function resolveUserEmpresaId(db, userId) {
  if (!await hasUsuariosEmpresasTable(db)) {
    const funcionarioEmpresa = await db.prepare(
      `
          SELECT f.empresa_id
          FROM usuarios u
          INNER JOIN funcionarios f ON f.id = u.funcionario_id
          WHERE u.id = ?
            AND u.deleted_at IS NULL
            AND f.deleted_at IS NULL
            AND f.empresa_id IS NOT NULL
          LIMIT 1
        `
    ).bind(userId).first();
    if (funcionarioEmpresa?.empresa_id) {
      return funcionarioEmpresa.empresa_id;
    }
    const activeEmpresas = await db.prepare(
      `
          SELECT e.id
          FROM empresas e
          WHERE e.deleted_at IS NULL
            AND e.ativo = 1
          ORDER BY
            CASE
              WHEN e.codigo = 'airtrust' THEN 0
              ELSE 1
            END,
            e.id ASC
          LIMIT 2
        `
    ).all();
    if ((activeEmpresas.results || []).length === 1) {
      return activeEmpresas.results[0].id;
    }
    throw unauthorized("Usu\xE1rio sem v\xEDnculo ativo com empresa", "USER_WITHOUT_EMPRESA");
  }
  const empresa = await db.prepare(
    `
        SELECT ue.empresa_id
        FROM usuarios_empresas ue
        INNER JOIN empresas e ON e.id = ue.empresa_id
        WHERE ue.usuario_id = ?
          AND e.deleted_at IS NULL
          AND e.ativo = 1
        ORDER BY
          CASE
            WHEN ue.is_primary = 1 THEN 0
            WHEN e.codigo = 'airtrust' THEN 1
            ELSE 2
          END,
          ue.empresa_id ASC
        LIMIT 1
      `
  ).bind(userId).first();
  if (!empresa?.empresa_id) {
    if (userId === 1) {
      const fallbackEmpresaAtiva = await db.prepare(
        `
            SELECT e.id AS empresa_id
            FROM empresas e
            WHERE e.deleted_at IS NULL
              AND e.ativo = 1
            ORDER BY
              CASE
                WHEN e.codigo = 'airtrust' THEN 0
                ELSE 1
              END,
              e.id ASC
            LIMIT 1
          `
      ).first();
      const fallbackEmpresa = fallbackEmpresaAtiva || await db.prepare(
        `
              SELECT e.id AS empresa_id
              FROM empresas e
              WHERE e.deleted_at IS NULL
              ORDER BY
                CASE
                  WHEN e.codigo = 'airtrust' THEN 0
                  ELSE 1
                END,
                e.id ASC
              LIMIT 1
            `
      ).first();
      if (fallbackEmpresa?.empresa_id) {
        await db.prepare(
          `INSERT OR IGNORE INTO usuarios_empresas (usuario_id, empresa_id, role, is_primary, created_at)
             VALUES (?, ?, 'admin', 1, datetime('now'))`
        ).bind(userId, fallbackEmpresa.empresa_id).run().catch(() => null);
        return fallbackEmpresa.empresa_id;
      }
    }
    const emailDomainResolved = await resolveEmpresaByEmailDomain(db, userId);
    if (emailDomainResolved) return emailDomainResolved;
    throw unauthorized("Usu\xE1rio sem v\xEDnculo ativo com empresa", "USER_WITHOUT_EMPRESA");
  }
  return empresa.empresa_id;
}
__name(resolveUserEmpresaId, "resolveUserEmpresaId");
async function resolveEmpresaByEmailDomain(db, userId) {
  const usuario = await db.prepare(`SELECT id, email FROM usuarios WHERE id = ? AND deleted_at IS NULL LIMIT 1`).bind(userId).first();
  if (!usuario?.email) return null;
  const atIndex = usuario.email.indexOf("@");
  if (atIndex === -1) return null;
  const domain2 = usuario.email.slice(atIndex + 1).toLowerCase();
  const empresa = await db.prepare(
    `SELECT id FROM empresas
       WHERE LOWER(dominio) = ?
         AND ativo = 1
         AND deleted_at IS NULL
       LIMIT 1`
  ).bind(domain2).first();
  if (!empresa?.id) return null;
  await db.prepare(
    `INSERT OR IGNORE INTO usuarios_empresas (usuario_id, empresa_id, role, is_primary, created_at)
       VALUES (?, ?, 'member', 1, datetime('now'))`
  ).bind(userId, empresa.id).run();
  return empresa.id;
}
