authRoutes.post("/change-password", auth(), async (c) => {
  const body = await c.req.json();
  const senhaAtual = String(body?.senhaAtual || body?.currentPassword || "");
  const novaSenha = String(body?.novaSenha || body?.newPassword || "");
  const confirmarSenha = String(body?.confirmarSenha || body?.confirmPassword || "");
  if (!senhaAtual) {
    throw badRequest("Senha atual \xE9 obrigat\xF3ria", "MISSING_CURRENT_PASSWORD");
  }
  validatePassword(novaSenha);
  if (confirmarSenha && confirmarSenha !== novaSenha) {
    throw badRequest("A confirma\xE7\xE3o da nova senha n\xE3o confere", "PASSWORD_CONFIRMATION_MISMATCH");
  }
  const userIdRaw = c.get("userId");
  const userId = typeof userIdRaw === "string" ? Number(userIdRaw) : userIdRaw;
  const db = c.env.DB;
  const { activeWhere } = await getUsuariosSchema(db);
  const user = await db.prepare(
    `SELECT id, password_hash
       FROM usuarios
       WHERE id = ?
         AND deleted_at IS NULL
         ${activeWhere}
       LIMIT 1`
  ).bind(userId).first();
  if (!user?.password_hash) {
    throw unauthorized("Usu\xE1rio n\xE3o encontrado", "USER_NOT_FOUND");
  }
  const devEnv = c.env.ENVIRONMENT ?? "production";
  const devBypassEnabled = devEnv === "development" && c.env.ENABLE_DEV_AUTH_BYPASS === "true";
  const senhaAtualValida = devBypassEnabled && user.password_hash === "dev-local-bypass" ? true : await verifyPassword(senhaAtual, user.password_hash);
  if (!senhaAtualValida) {
    throw unauthorized("Senha atual inv\xE1lida", "INVALID_CURRENT_PASSWORD");
  }
  if (!(devBypassEnabled && user.password_hash === "dev-local-bypass")) {
    const isSamePassword = await verifyPassword(novaSenha, user.password_hash);
    if (isSamePassword) {
      throw badRequest("A nova senha deve ser diferente da atual", "PASSWORD_UNCHANGED");
    }
  }
  const passwordHash = await hashPassword(novaSenha);
  await db.prepare(`UPDATE usuarios SET password_hash = ?, updated_at = datetime('now') WHERE id = ?`).bind(passwordHash, userId).run();
  return c.json({
    success: true,
    message: "Senha alterada com sucesso."
  });
});
authRoutes.get("/empresas", auth(), async (c) => {
  const userIdRaw = c.get("userId");
  const userId = typeof userIdRaw === "string" ? Number(userIdRaw) : userIdRaw;
  const db = c.env.DB;
  const empresaIdAtual = await resolveUserEmpresaId(db, userId);
  const isPlatformAdmin = userId === 1;
  const empresas = await db.prepare(
    isPlatformAdmin ? `
      SELECT
        e.id,
        e.nome,
        e.codigo,
        e.logo_url,
        'admin' AS role,
        CASE WHEN e.id = ? THEN 1 ELSE 0 END AS is_primary,
        CASE WHEN e.id = ? THEN 1 ELSE 0 END AS is_current
      FROM empresas e
      WHERE e.deleted_at IS NULL
        AND e.ativo = 1
      ORDER BY
        CASE WHEN e.id = ? THEN 0 ELSE 1 END,
        CASE WHEN e.codigo = 'airtrust' THEN 0 ELSE 1 END,
        e.nome ASC
    ` : `
      SELECT
        e.id,
        e.nome,
        e.codigo,
        e.logo_url,
        ue.role,
        ue.is_primary,
        CASE WHEN e.id = ? THEN 1 ELSE 0 END AS is_current
      FROM usuarios_empresas ue
      INNER JOIN empresas e ON e.id = ue.empresa_id
      WHERE ue.usuario_id = ?
        AND e.deleted_at IS NULL
        AND e.ativo = 1
      ORDER BY
        CASE WHEN e.id = ? THEN 0 ELSE 1 END,
        CASE WHEN ue.is_primary = 1 THEN 0 ELSE 1 END,
        e.nome ASC
    `
  ).bind(
    ...isPlatformAdmin ? [empresaIdAtual, empresaIdAtual, empresaIdAtual] : [empresaIdAtual, userId, empresaIdAtual]
  ).all();
  return c.json({
    success: true,
    data: {
      empresaAtualId: empresaIdAtual,
      empresas: empresas.results || []
    }
  });
});
authRoutes.post("/select-empresa", auth(), async (c) => {
  const body = await c.req.json();
  const targetEmpresaId = Number(body?.empresaId || 0);
  if (!targetEmpresaId || !Number.isFinite(targetEmpresaId)) {
    throw badRequest("empresaId \xE9 obrigat\xF3rio", "MISSING_EMPRESA_ID");
  }
  const userIdRaw = c.get("userId");
  const userId = typeof userIdRaw === "string" ? Number(userIdRaw) : userIdRaw;
  const db = c.env.DB;
  const isPlatformAdmin = userId === 1;
  const vinculo = await db.prepare(
    isPlatformAdmin ? `
      SELECT 'admin' AS role, e.id as empresa_id, e.nome as empresa_nome, e.codigo as empresa_codigo
      FROM empresas e
      WHERE e.id = ?
        AND e.deleted_at IS NULL
        AND e.ativo = 1
      LIMIT 1
    ` : `
      SELECT ue.role, e.id as empresa_id, e.nome as empresa_nome, e.codigo as empresa_codigo
      FROM usuarios_empresas ue
      INNER JOIN empresas e ON e.id = ue.empresa_id
      WHERE ue.usuario_id = ?
        AND ue.empresa_id = ?
        AND e.deleted_at IS NULL
        AND e.ativo = 1
      LIMIT 1
    `
  ).bind(...isPlatformAdmin ? [targetEmpresaId] : [userId, targetEmpresaId]).first();
  if (!vinculo) {
    throw unauthorized("Usu\xE1rio n\xE3o possui acesso \xE0 empresa selecionada", "TENANT_ACCESS_DENIED");
  }
  if (isPlatformAdmin) {
    await db.prepare(
      `INSERT OR IGNORE INTO usuarios_empresas (usuario_id, empresa_id, role, is_primary, created_at)
         VALUES (?, ?, 'admin', 1, datetime('now'))`
    ).bind(userId, targetEmpresaId).run().catch(() => null);
  }
  await db.prepare(
    `
      UPDATE usuarios_empresas
      SET is_primary = CASE WHEN empresa_id = ? THEN 1 ELSE 0 END
      WHERE usuario_id = ?
    `
  ).bind(targetEmpresaId, userId).run();
  const user = await db.prepare(
    `
      SELECT id, email, perfil, nome
      FROM usuarios
      WHERE id = ? AND deleted_at IS NULL
      LIMIT 1
    `
  ).bind(userId).first();
  if (!user) {
    throw unauthorized("Usu\xE1rio n\xE3o encontrado", "USER_NOT_FOUND");
  }
  const { token: accessToken } = await issueAccessTokenForEmpresa(c, {
    userId,
    email: user.email,
    role: user.perfil,
    nome: user.nome,
    empresaId: targetEmpresaId
  });
  return c.json({
    success: true,
    data: {
      accessToken,
      empresa: {
        id: vinculo.empresa_id,
        nome: vinculo.empresa_nome,
        codigo: vinculo.empresa_codigo
      }
    }
  });
});
authRoutes.post("/impersonate", auth(), async (c) => {
  const logger = createLogger(c, "AuthRoutes.impersonate");
  try {
    const callerRole = c.get("userRole")?.toUpperCase() ?? "";
    if (callerRole !== "ADMIN") {
      throw unauthorized("Apenas administradores podem usar impersona\xE7\xE3o", "FORBIDDEN");
    }
    const callerId = c.get("userId");
    const body = await c.req.json();
    const targetUserId = Number(body?.userId);
    if (!targetUserId || isNaN(targetUserId)) {
      throw badRequest("userId inv\xE1lido", "INVALID_USER_ID");
    }
    if (Number(callerId) === targetUserId) {
      throw badRequest("N\xE3o \xE9 poss\xEDvel impersonar a si mesmo", "SELF_IMPERSONATE");
    }
    const db = c.env.DB;
    const target = await db.prepare(
      `SELECT id, email, perfil, nome FROM usuarios WHERE id = ? AND deleted_at IS NULL LIMIT 1`
    ).bind(targetUserId).first();
    if (!target) {
      throw unauthorized("Usu\xE1rio alvo n\xE3o encontrado", "USER_NOT_FOUND");
    }
    const empresaId = await resolveUserEmpresaId(db, target.id);
    const permissoesRows = await db.prepare(
      `SELECT permissao, tipo FROM usuario_permissoes WHERE usuario_id = ? ORDER BY permissao`
    ).bind(target.id).all().catch(() => ({ results: [] }));
    const permissions = (permissoesRows.results || []).map((p) => `${p.tipo}:${p.permissao}`);
    const userFull = await db.prepare(`SELECT funcionario_id FROM usuarios WHERE id = ? LIMIT 1`).bind(target.id).first().catch(() => null);
    const jwtSecret = c.env.JWT_SECRET;
    if (!jwtSecret) throw new Error("JWT_SECRET n\xE3o configurado");
    const { token: accessToken } = await generateJWT(
      {
        sub: target.id,
        empresa_id: empresaId,
        email: target.email,
        role: target.perfil.toUpperCase(),
        nome: target.nome,
        permissions: permissions.length > 0 ? permissions : void 0,
        funcionario_id: userFull?.funcionario_id ?? null,
        impersonated_by: Number(callerId)
      },
      jwtSecret,
      3600
    );
    logger.info(
      `[IMPERSONATE] Admin ${callerId} impersonando usu\xE1rio ${target.id} (${target.email})`
    );
    await logAudit(db, {
      userId: Number(callerId),
      action: "USUARIO_IMPERSONADO",
      entityType: "usuario",
      entityId: targetUserId,
      newValues: {
        target_id: targetUserId,
        target_email: target.email,
        target_nome: target.nome,
        impersonation_duration: "3600 segundos"
      }
    }).catch((err2) => {
      logger.warn("[IMPERSONATE] Falha ao registrar auditoria", toError(err2));
    });
    return c.json({
      success: true,
      data: {
        accessToken,
        user: {
          id: target.id,
          email: target.email,
          nome: target.nome,
          role: target.perfil.toUpperCase(),
          permissions,
          funcionario_id: userFull?.funcionario_id ?? null
        }
      }
    });
  } catch (error4) {
    if (error4?.name === "ApiError") throw error4;
    logger.error("[IMPERSONATE] Erro", toError(error4));
    throw internalError("Erro ao processar impersona\xE7\xE3o", "IMPERSONATE_ERROR");
  }
});

