async function verificarHabilitacaoModelo(db, funcionarioId, aeronaveId, empresaId) {
  const aeronave = await db.prepare(
    `SELECT prefixo, modelo FROM aeronaves
        WHERE id = ?
          AND deleted_at IS NULL
          AND UPPER(COALESCE(NULLIF(TRIM(status), ''), 'ATIVO')) = 'ATIVO'
        LIMIT 1`
  ).bind(aeronaveId).first();
  if (!aeronave) return { habilitado: false, motivo: "Aeronave n\xE3o encontrada" };
  const piloto = await db.prepare(
    `SELECT modelo_aeronave_id FROM funcionarios
        WHERE id = ?
          AND deleted_at IS NULL
          AND COALESCE(ativo, 1) = 1
          AND UPPER(COALESCE(NULLIF(TRIM(status), ''), 'ATIVO')) = 'ATIVO'
          AND (empresa_id IS NULL OR empresa_id = ?)
        LIMIT 1`
  ).bind(funcionarioId, empresaId).first();
  if (!piloto) return { habilitado: false, motivo: "Funcion\xE1rio n\xE3o encontrado" };
  if (!piloto.modelo_aeronave_id) return { habilitado: true };
  const modeloAeronave = String(aeronave.modelo || "").trim().toUpperCase().replace(/[\s-]+/g, "");
  const tokens = String(piloto.modelo_aeronave_id).split(",").map((t) => t.trim()).filter(Boolean);
  if (!tokens.length) return { habilitado: true };
  const placeholders = tokens.map(() => "?").join(",");
  const rows = await db.prepare(
    `SELECT modelo, codigo FROM modelos_aeronave WHERE CAST(id AS TEXT) IN (${placeholders})`
  ).bind(...tokens).all();
  const habilitacoes = [
    ...tokens,
    ...(rows.results || []).flatMap((r) => [
      String(r.modelo || "").toUpperCase().replace(/[\s-]+/g, ""),
      String(r.codigo || "").toUpperCase().replace(/[\s-]+/g, "")
    ])
  ].filter(Boolean);
  const modelosAeronave2 = [modeloAeronave];
  if (modeloAeronave === "SK76") modelosAeronave2.push("S76");
  if (modeloAeronave === "S76") modelosAeronave2.push("SK76");
  const habilitado = modelosAeronave2.some((m) => habilitacoes.includes(m));
  if (!habilitado) {
    return {
      habilitado: false,
      motivo: `Funcion\xE1rio n\xE3o habilitado para ${aeronave.prefixo} (${aeronave.modelo || "modelo n\xE3o informado"})`
    };
  }
  return { habilitado: true };
}
