var app31 = new Hono2();
app31.use("*", auth(), requireRole("admin"));
app31.post("/", async (c) => {
  try {
    const db = c.env.DB;
    const logger = createLogger(c, "FixRenovadas");
    const startTime = Date.now();
    const empresaId = Number(c.get("empresaId") || 0);
    if (!Number.isFinite(empresaId) || empresaId <= 0) {
      throw new AppError("Empresa n\xE3o identificada no contexto", 401, "TENANT_REQUIRED");
    }
    logger.info("Iniciando corre\xE7\xE3o autom\xE1tica de renovadas", { empresaId });
    const { results: grupos } = await db.prepare(
      `
        SELECT 
          funcionario_cpf,
          qualificacao_codigo,
          COUNT(*) as total
        FROM qualificacoes_historico
        WHERE deleted_at IS NULL
          AND empresa_id = ?
        GROUP BY funcionario_cpf, qualificacao_codigo
        HAVING COUNT(*) > 1
      `
    ).bind(empresaId).all();
    logger.info("Grupos encontrados para processamento", {
      empresaId,
      totalGrupos: grupos?.length || 0
    });
    let totalVinculadas = 0;
    let totalRenovadas = 0;
    for (const grupo of grupos || []) {
      const g = grupo;
      const { results: registros } = await db.prepare(
        `
          SELECT id, data_conclusao, status
          FROM qualificacoes_historico
          WHERE funcionario_cpf = ?
            AND qualificacao_codigo = ?
            AND empresa_id = ?
            AND deleted_at IS NULL
          ORDER BY data_conclusao ASC
        `
      ).bind(g.funcionario_cpf, g.qualificacao_codigo, empresaId).all();
      if (!registros || registros.length <= 1) continue;
      for (let i = 1; i < registros.length; i++) {
        const atual = registros[i];
        const anterior = registros[i - 1];
        await db.prepare(
          `
            UPDATE qualificacoes_historico
            SET renovacao_de = ?, updated_at = datetime('now')
            WHERE id = ?
          `
        ).bind(anterior.id, atual.id).run();
        totalVinculadas++;
        if (anterior.status !== "renovada") {
          await db.prepare(
            `
              UPDATE qualificacoes_historico
              SET status = 'renovada', updated_at = datetime('now')
              WHERE id = ?
            `
          ).bind(anterior.id).run();
          totalRenovadas++;
        }
      }
    }
    const executionTime = Date.now() - startTime;
    logger.info("Corre\xE7\xE3o de renovadas conclu\xEDda", {
      empresaId,
      totalGruposProcessados: grupos?.length || 0,
      totalRenovadas,
      totalVinculadas,
      executionTimeMs: executionTime
    });
    return c.json({
      success: true,
      message: "Renovadas corrigidas com sucesso",
      data: {
        empresa_id: empresaId,
        total_grupos_processados: grupos?.length || 0,
        total_renovadas: totalRenovadas,
        total_vinculadas: totalVinculadas,
        execution_time_ms: executionTime
      }
    });
  } catch (error4) {
    createLogger(c, "FixRenovadas").error("Erro ao corrigir renovadas", toError(error4));
    if (error4 instanceof AppError) {
      return c.json(
        {
          success: false,
          error: error4.message,
          code: error4.code
        },
        error4.status
      );
    }
    return c.json(
      {
        success: false,
        error: "Erro ao corrigir renovadas",
        details: error4 instanceof Error ? error4.message : "Erro desconhecido"
      },
      500
    );
  }
});
