app36.post("/executar/:entidade", async (c) => {
  const logger = createLogger(c, "ImportacaoRoute");
  try {
    const entidade = c.req.param("entidade");
    const db = c.env.DB;
    logger.info("Request de execu\xE7\xE3o recebida", {
      entidade,
      method: "POST /executar"
    });
    const service = getImportService(entidade, db);
    if (!service) {
      logger.warn("Entidade inv\xE1lida solicitada", { entidade });
      return c.json({ success: false, error: `Entidade inv\xE1lida: ${entidade}` }, 400);
    }
    const formData = await c.req.formData();
    const file = formData.get("file");
    const mode = formData.get("mode") || "UPSERT";
    logger.debug("Par\xE2metros recebidos", { mode, has_file: !!file });
    if (!file || typeof file === "string") {
      logger.warn("Arquivo n\xE3o enviado ou inv\xE1lido");
      return c.json({ success: false, error: "Arquivo n\xE3o enviado" }, 400);
    }
    const validModes = entidade === "historico" || entidade === "qualificacoes_historico" ? ["INSERT", "UPSERT"] : ["INSERT", "UPDATE", "UPSERT"];
    if (!validModes.includes(mode)) {
      logger.warn("Mode inv\xE1lido", { mode, valid_modes: validModes });
      return c.json({ success: false, error: `Mode inv\xE1lido. Use ${validModes.join(", ")}` }, 400);
    }
    const buffer = await file.arrayBuffer();
    const parsed = await parseImportFile(buffer, file.type);
    logger.info("Arquivo parseado para execu\xE7\xE3o", {
      total_linhas: parsed.rows.length,
      mode
    });
    const remappedRows = parsed.rows.map(
      (row) => remapRowHeaders(
        row,
        entidade
      )
    );
    const timer = logger.startTimer(`Importa\xE7\xE3o completa (mode: ${mode})`);
    const result = await service.import(
      remappedRows,
      mode
    );
    timer();
    logger.info("Importa\xE7\xE3o conclu\xEDda", {
      success: result.success,
      inserted: result.inserted,
      updated: result.updated,
      skipped: result.skipped,
      errors_count: result.errors.length
    });
    if (!result.success && result.errors.length > 0) {
      logger.error("Importa\xE7\xE3o com erros", void 0, {
        total_erros: result.errors.length,
        primeiro_erro: result.errors[0]
      });
    }
    return c.json({
      success: result.success,
      totalRows: result.totalRows,
      inserted: result.inserted,
      updated: result.updated,
      skipped: result.skipped,
      errors: result.errors,
      message: result.success ? `Importa\xE7\xE3o conclu\xEDda: ${result.inserted} inseridos, ${result.updated} atualizados, ${result.skipped} ignorados` : `Importa\xE7\xE3o falhou com ${result.errors.length} erros`
    });
  } catch (error4) {
    logger.fatal("Erro ao executar importa\xE7\xE3o", error4);
    return c.json(
      {
        success: false,
        error: error4 instanceof Error ? error4.message : "Erro desconhecido"
      },
      500
    );
  }
});
