app39.put("/usuarios/:usuarioId/acessos", requireTenantRole("admin"), async (c) => {
  const db = c.env.DB;
  const usuarioId = parseInt(c.req.param("usuarioId"), 10);
  const tenantCtx = getTenantContext(c);
  const body = await c.req.json();
  const acessos = Array.isArray(body.acessos) ? body.acessos.map((item) => ({
    empresaId: Number(item.empresaId),
    role: String(item.role || "viewer"),
    modulosAtivos: Array.isArray(item.modulosAtivos) ? item.modulosAtivos : []
  })).filter((item) => Number.isFinite(item.empresaId) && item.empresaId > 0) : [];
  if (acessos.length === 0) {
    throw new AppError("Informe ao menos um acesso de empresa", 400);
  }
  if (tenantCtx.empresaCodigo !== "airtrust") {
    const invalid = acessos.find((item) => item.empresaId !== tenantCtx.empresaId);
    if (invalid) {
      throw new AppError("Sem permiss\xE3o para editar acessos de outras empresas", 403);
    }
  }
  const usuario = await db.prepare("SELECT id FROM usuarios WHERE id = ? AND deleted_at IS NULL").bind(usuarioId).first();
  if (!usuario) {
    throw new AppError("Usu\xE1rio n\xE3o encontrado", 404);
  }
  const { hasModulosAtivos } = await getUsuariosEmpresasFeatures(db);
  await db.prepare(
    tenantCtx.empresaCodigo === "airtrust" ? "DELETE FROM usuarios_empresas WHERE usuario_id = ?" : "DELETE FROM usuarios_empresas WHERE usuario_id = ? AND empresa_id = ?"
  ).bind(
    ...tenantCtx.empresaCodigo === "airtrust" ? [usuarioId] : [usuarioId, tenantCtx.empresaId]
  ).run();
  let isPrimarySet = false;
  for (const acesso of acessos) {
    const isPrimary = !isPrimarySet ? 1 : 0;
    isPrimarySet = true;
    if (hasModulosAtivos) {
      await db.prepare(
        `
          INSERT INTO usuarios_empresas (usuario_id, empresa_id, role, is_primary, modulos_ativos)
          VALUES (?, ?, ?, ?, ?)
        `
      ).bind(
        usuarioId,
        acesso.empresaId,
        acesso.role,
        isPrimary,
        JSON.stringify(acesso.modulosAtivos)
      ).run();
    } else {
      await db.prepare(
        `
          INSERT INTO usuarios_empresas (usuario_id, empresa_id, role, is_primary)
          VALUES (?, ?, ?, ?)
        `
      ).bind(usuarioId, acesso.empresaId, acesso.role, isPrimary).run();
    }
  }
  return c.json({
    success: true,
    message: "Acessos do usu\xE1rio atualizados com sucesso"
  });
});
