empresasRoutes.put("/:id", requireTenantRole("admin"), async (c) => {
  const db = c.env.DB;
  const id = parseInt(c.req.param("id"), 10);
  const tenantCtx = getTenantContext(c);
  try {
    if (!isPlatformSuperAdmin(c) && tenantCtx.empresaId !== id) {
      throw new AppError("Sem permiss\xE3o para editar esta empresa", 403);
    }
    const body = await c.req.json();
    console.log("[PUT /empresas/:id] Body recebido:", JSON.stringify(body));
    if (body.nome !== void 0 && (typeof body.nome !== "string" || body.nome.trim().length < 2)) {
      throw new AppError("Nome deve ter pelo menos 2 caracteres", 400);
    }
    const exists = await db.prepare("SELECT id FROM empresas WHERE id = ? AND deleted_at IS NULL").bind(id).first();
    if (!exists) {
      if (id === 1 && isPlatformSuperAdmin(c)) {
        await db.prepare(
          `
          INSERT INTO empresas (id, nome, codigo, plano, max_funcionarios, max_storage_mb, ativo, created_at, updated_at) 
          VALUES (1, ?, 'airtrust', ?, ?, ?, 1, datetime('now'), datetime('now'))
        `
        ).bind(
          body.nome || "AirTrust System",
          body.plano || "enterprise",
          body.max_funcionarios || 1e3,
          body.max_storage_mb || 10240
        ).run();
        await db.prepare(
          `
          INSERT INTO empresas_config (empresa_id)
          VALUES (1)
        `
        ).run();
        if (body.cnpj) {
          await db.prepare("UPDATE empresas SET cnpj = ? WHERE id = 1").bind(body.cnpj).run();
        }
        return c.json({
          success: true,
          message: "Empresa AirTrust recriada e atualizada com sucesso"
        });
      }
      throw new AppError("Empresa n\xE3o encontrada", 404);
    }
    const allowedFields = [
      "nome",
      "cnpj",
      "logo_url",
      "plano",
      "max_funcionarios",
      "max_storage_mb",
      "ativo",
      // ✅ Adicionado para permitir ativar/desativar empresa
      "dominio"
      // ✅ Domínio de e-mail para auto-detecção de empresa no login
    ];
    const fields = [];
    const values2 = [];
    console.log("[PUT /empresas/:id] Iterando campos do body:", Object.keys(body));
    for (const [key, value] of Object.entries(body)) {
      if (value !== void 0 && allowedFields.includes(key)) {
        fields.push(`${key} = ?`);
        values2.push(value);
      }
    }
    if (fields.length === 0) {
      throw new AppError("Nenhum campo para atualizar", 400);
    }
    fields.push("updated_at = datetime('now')");
    values2.push(id);
    await db.prepare(
      `
    UPDATE empresas SET ${fields.join(", ")} WHERE id = ?
  `
    ).bind(...values2).run();
    const ua2 = extrairUsuarioAuditoria(c);
    await registrarAuditoria({ db, tabela: "empresas", acao: "UPDATE", registro_id: id, ...ua2 });
    return c.json({
      success: true,
      message: "Empresa atualizada com sucesso"
    });
  } catch (error4) {
    createLogger(c, "Empresas").error("PUT /:id erro ao atualizar empresa", toError(error4));
    if (error4 && typeof error4 === "object" && "name" in error4 && error4.name === "ZodError") {
      return c.json(
        {
          success: false,
          error: "Erro de valida\xE7\xE3o",
          details: "errors" in error4 ? error4.errors : void 0
        },
        400
      );
    }
    if (error4 instanceof AppError) throw error4;
    return c.json(
      {
        success: false,
        error: "Erro interno do servidor"
      },
      500
    );
  }
});
