empresasRoutes.post("/:id/logo", requireTenantRole("admin"), async (c) => {
  const db = c.env.DB;
  const bucket = c.env.BUCKET;
  if (!bucket) {
    createLogger(c, "Empresas").error("Bucket R2 n\xE3o configurado no ambiente");
    return c.json({ success: false, error: "Storage n\xE3o configurado" }, 500);
  }
  const id = parseInt(c.req.param("id"), 10);
  const target = c.req.query("target") || "empresa";
  const tenantCtx = getTenantContext(c);
  if (!isPlatformSuperAdmin(c) && tenantCtx.empresaId !== id) {
    throw new AppError("Sem permiss\xE3o para alterar logo desta empresa", 403);
  }
  const empresa = await db.prepare("SELECT codigo FROM empresas WHERE id = ? AND deleted_at IS NULL").bind(id).first();
  if (!empresa) {
    throw new AppError("Empresa n\xE3o encontrada", 404);
  }
  const form = await c.req.formData();
  const file = form.get("file");
  if (!file) {
    throw new AppError("Arquivo obrigat\xF3rio", 400);
  }
  const MAX_SIZE = target === "sistema-logo" ? 10 * 1024 * 1024 : target === "sistema-favicon" ? 10 * 1024 * 1024 : 2 * 1024 * 1024;
  if (file.size > MAX_SIZE) {
    const maxSizeLabel = target === "sistema-logo" || target === "sistema-favicon" ? "10MB" : "2MB";
    throw new AppError(`Tamanho m\xE1ximo excedido (${maxSizeLabel})`, 400);
  }
  if (target === "sistema-logo" || target === "sistema-favicon") {
    if (file.type !== "image/png") {
      throw new AppError("Para logo/favicon do sistema, apenas PNG \xE9 permitido", 400);
    }
  } else if (!file.type.startsWith("image/")) {
    throw new AppError("Apenas imagens s\xE3o permitidas", 400);
  } else if (!["image/png", "image/jpeg", "image/jpg", "image/webp", "image/gif", "image/svg+xml"].includes(
    file.type.toLowerCase()
  )) {
    throw new AppError("Formato inv\xE1lido. Use PNG, JPG, WEBP, GIF ou SVG.", 400);
  }
  try {
    const fileExt = inferImageExtension(file.name, file.type);
    const cacheBuster = Date.now();
    const r2Key = target === "certificado" ? `empresas/${id}/certificado-logo-${cacheBuster}.${fileExt}` : target === "sistema-favicon" ? `empresas/${id}/favicon-${cacheBuster}.${fileExt}` : target === "sistema-logo" ? `empresas/${id}/sistema-logo-${cacheBuster}.${fileExt}` : `empresas/${id}/logo-${cacheBuster}.${fileExt}`;
    await bucket.put(r2Key, file.stream(), {
      httpMetadata: {
        contentType: file.type
      },
      customMetadata: {
        empresa_id: String(id),
        codigo: empresa.codigo,
        uploaded_at: (/* @__PURE__ */ new Date()).toISOString(),
        target
      }
    });
    const publicUrl = `/api/assets/${r2Key}`;
    if (target === "certificado") {
      await db.prepare(
        `
        INSERT INTO empresas_config (empresa_id, certificado_logo_url)
        VALUES (?, ?)
        ON CONFLICT(empresa_id) DO UPDATE SET
          certificado_logo_url = excluded.certificado_logo_url,
          updated_at = datetime('now')
      `
      ).bind(id, publicUrl).run();
    } else if (target === "sistema-logo" || target === "sistema-favicon") {
      await saveEmpresaSystemSettings(db, id, {
        ...target === "sistema-logo" ? { logoUrl: publicUrl } : {},
        ...target === "sistema-favicon" ? { faviconUrl: publicUrl } : {}
      });
      if (target === "sistema-logo") {
        await db.prepare("UPDATE empresas SET logo_url = ?, updated_at = datetime('now') WHERE id = ?").bind(publicUrl, id).run();
      }
    } else {
      await db.prepare("UPDATE empresas SET logo_url = ?, updated_at = datetime('now') WHERE id = ?").bind(publicUrl, id).run();
    }
    return c.json({
      success: true,
      data: {
        logo_url: publicUrl,
        target
      },
      message: "Logo atualizado com sucesso"
    });
  } catch (error4) {
    createLogger(c, "Empresas").error("Erro no upload de logo", toError(error4));
    throw new AppError("Erro ao fazer upload do logo", 500);
  }
});
