        voo_horas: +(t.total_voo_min / 60).toFixed(1),
        pct_jornada: +pctJornada.toFixed(1),
        pct_voo: +pctVoo.toFixed(1),
        dias_jornada: t.dias_jornada,
        dia_ciclo: t.max_dia_ciclo,
        alerta: alertaGeral,
