sgso.post("/relatos/:id/avaliacao-risco", async (c) => {
  try {
    const empresaId = getEmpresaId(c);
    const uid = getUid3(c);
    const db = c.env.DB;
    const { id } = c.req.param();
    const body = await c.req.json();
    const schema = z.object({
      tipo_avaliacao: z.enum(["INICIAL", "RESIDUAL"]),
      probabilidade: z.enum(["A", "B", "C", "D", "E"]),
      severidade: z.number().int().min(1).max(5),
      perfil_id: z.number().int().optional(),
      justificativa: z.string().optional()
    });
    const parsed = schema.safeParse(body);
    if (!parsed.success) {
      return c.json(
        { success: false, error: "Dados inv\xE1lidos", details: parsed.error.flatten() },
        400
      );
    }
    const d = parsed.data;
    const relato = await db.prepare(
      "SELECT id, efetividade_cognitiva FROM sgso_relatos WHERE id = ? AND empresa_id = ? AND deleted_at IS NULL"
    ).bind(id, empresaId).first();
    if (!relato) {
      return c.json(
        { success: false, error: "Relato n\xE3o encontrado", code: "SGSO_RELATO_NOT_FOUND" },
        404
      );
    }
    let probFinal = d.probabilidade;
    let elevadoPorFadiga = 0;
    let justificativaElevacao = null;
    const efetividade = relato.efetividade_cognitiva;
    if (efetividade !== null && efetividade < 70) {
      const probAnterior = probFinal;
      probFinal = elevarProbabilidade(probFinal);
      if (probFinal !== probAnterior) {
        elevadoPorFadiga = 1;
        justificativaElevacao = `Probabilidade elevada automaticamente de ${probAnterior} para ${probFinal} devido \xE0 efetividade cognitiva do piloto (${efetividade.toFixed(1)}%) estar abaixo de 70% conforme pol\xEDtica FRMS.`;
      }
    }
    const nivelRisco = calcularNivelRisco(probFinal, d.severidade);
    const ts = now6();
    const perfil = await db.prepare(
      `SELECT id, codigo
         FROM sgso_matriz_risco_perfis
         WHERE ativo = 1 AND (empresa_id = ? OR empresa_id = 0)
           ${d.perfil_id ? "AND id = ?" : ""}
         ORDER BY CASE WHEN empresa_id = ? THEN 0 ELSE 1 END, padrao DESC, id ASC
         LIMIT 1`
    ).bind(...d.perfil_id ? [empresaId, d.perfil_id, empresaId] : [empresaId, empresaId]).first();
    const celula = perfil ? await db.prepare(
      `SELECT score, nivel_risco, exige_aprovacao
             FROM sgso_matriz_risco_celulas
             WHERE perfil_id = ? AND codigo_probabilidade = ? AND severidade = ?`
    ).bind(perfil.id, probFinal, d.severidade).first() : null;
    const nivelRiscoFinal = celula?.nivel_risco ?? nivelRisco;
    const result = await db.prepare(
      `INSERT INTO sgso_avaliacao_risco
         (relato_id, empresa_id, tipo_avaliacao, probabilidade, severidade, nivel_risco,
          probabilidade_original, elevado_por_fadiga, justificativa_elevacao,
          justificativa, avaliador_id, data_avaliacao, created_at, updated_at)
         VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`
    ).bind(
      id,
      empresaId,
      d.tipo_avaliacao,
      probFinal,
      d.severidade,
      nivelRiscoFinal,
      elevadoPorFadiga ? d.probabilidade : null,
      elevadoPorFadiga,
      justificativaElevacao,
      d.justificativa ?? null,
      uid,
      ts,
      ts,
      ts
    ).run();
    if (perfil) {
      await db.prepare(
        `INSERT INTO sgso_avaliacao_risco_contexto
           (avaliacao_risco_id, empresa_id, perfil_id, score_calculado, apetite_violado,
            exige_aprovacao, aprovacao_status, snapshot_json, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
      ).bind(
        result.meta.last_row_id,
        empresaId,
        perfil.id,
        celula?.score ?? 0,
        nivelRiscoFinal === "CRITICO" ? 1 : 0,
        celula?.exige_aprovacao ?? 0,
        (celula?.exige_aprovacao ?? 0) === 1 ? "PENDENTE" : "NAO_APLICAVEL",
        JSON.stringify({
          perfil_codigo: perfil.codigo,
          probabilidade_original: d.probabilidade,
          probabilidade_final: probFinal,
          severidade: d.severidade,
          nivel_risco: nivelRiscoFinal
        }),
        ts,
        ts
      ).run();
    }
    return c.json(
      {
        success: true,
        data: {
          id: result.meta.last_row_id,
          nivel_risco: nivelRiscoFinal,
          probabilidade: probFinal,
          elevado_por_fadiga: elevadoPorFadiga === 1,
          justificativa_elevacao: justificativaElevacao,
          perfil_id: perfil?.id ?? null,
          exige_aprovacao: (celula?.exige_aprovacao ?? 0) === 1
        }
      },
      201
    );
  } catch (err2) {
    return sgsoErrorResponse2(c, err2, "Erro ao salvar avalia\xE7\xE3o", "SGSO_AVALIACAO_RISCO_SAVE_ERROR");
  }
});
