extra.post("/frat/avaliacoes", async (c) => {
  try {
    const empresaId = getEmpresaId(c);
    const uid = getUid(c);
    const db = c.env.DB;
    const body = await c.req.json();
    const parsed = FratEvaluationSchema.safeParse(body);
    if (!parsed.success) {
      return c.json(
        { success: false, error: "Dados inv\xE1lidos", details: parsed.error.flatten() },
        400
      );
    }
    const d = parsed.data;
    const modelo = await db.prepare(
      "SELECT * FROM sgso_frat_modelos WHERE id = ? AND (empresa_id = ? OR empresa_id = 0) AND ativo = 1"
    ).bind(d.modelo_id, empresaId).first();
    if (!modelo) return c.json({ success: false, error: "Modelo FRAT n\xE3o encontrado" }, 404);
    const fatores = await db.prepare(
      "SELECT id, codigo, tipo_resposta, peso_base, regra_score_json FROM sgso_frat_fatores WHERE modelo_id = ? AND ativo = 1 ORDER BY ordem_exibicao ASC"
    ).bind(d.modelo_id).all();
    const scored = scoreFratResponses(fatores.results, d.respostas);
    const exigeAprovacao = ["ALTO", "CRITICO"].includes(scored.level) ? 1 : 0;
    const avaliacaoId = uuid2();
    const ts = now4();
    await db.prepare(
      `INSERT INTO sgso_frat_avaliacoes
         (id, empresa_id, modelo_id, escala_id, alocacao_id, tripulante_id, aeronave_id,
          data_operacao, score_total, nivel_risco, status, exige_aprovacao, despacho_bloqueado,
          origem_vinculo, frms_fadiga_checkin_id, justificativa, created_by, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'SUBMETIDO', ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(
      avaliacaoId,
      empresaId,
      d.modelo_id,
      d.escala_id ?? null,
      d.alocacao_id ?? null,
      d.tripulante_id ?? null,
      d.aeronave_id ?? null,
      d.data_operacao,
      scored.totalScore,
      scored.level,
      exigeAprovacao,
      exigeAprovacao,
      d.origem_vinculo ?? "MANUAL",
      d.frms_fadiga_checkin_id ?? null,
      d.justificativa ?? null,
      uid,
      ts,
      ts
    ).run();
    for (const answer of d.respostas) {
      const scoredAnswer = scored.responseScores.find((item) => item.fatorId === answer.fator_id);
      await db.prepare(
        `INSERT INTO sgso_frat_respostas
           (avaliacao_id, fator_id, empresa_id, resposta_texto, resposta_numero, score_aplicado, observacao, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
      ).bind(
        avaliacaoId,
        answer.fator_id,
        empresaId,
        scoredAnswer?.textValue ?? (typeof answer.resposta === "number" ? null : String(answer.resposta)),
        scoredAnswer?.numberValue ?? (typeof answer.resposta === "number" ? answer.resposta : null),
        scoredAnswer?.score ?? 0,
        answer.observacao ?? null,
        ts
      ).run();
    }
    await insertAuditTrail(db, empresaId, "FRAT_AVALIACAO", avaliacaoId, "CRIADA", uid, {
      score_total: scored.totalScore,
      nivel_risco: scored.level,
      exige_aprovacao: Boolean(exigeAprovacao)
    });
    if (d.frms_fadiga_checkin_id) {
      try {
        await db.prepare(
          `UPDATE frms_fadiga_checkin
             SET associado_frat_avaliacao_id = ?,
                 frat_sugerido_nivel = ?,
                 updated_at = datetime('now')
             WHERE empresa_id = ?
               AND id = ?
               AND deleted_at IS NULL`
        ).bind(avaliacaoId, scored.level, empresaId, d.frms_fadiga_checkin_id).run();
      } catch (linkErr) {
        console.warn("[SGSO NEXT] FRAT bridge por checkin_id n\xE3o aplicado:", linkErr);
      }
    } else if (d.tripulante_id && d.data_operacao) {
      try {
        await db.prepare(
          `UPDATE frms_fadiga_checkin
             SET associado_frat_avaliacao_id = ?,
                 frat_sugerido_nivel = ?,
                 updated_at = datetime('now')
             WHERE empresa_id = ?
               AND funcionario_id = ?
               AND data_checkin = ?
               AND deleted_at IS NULL`
        ).bind(avaliacaoId, scored.level, empresaId, d.tripulante_id, d.data_operacao).run();
      } catch (linkErr) {
        console.warn("[SGSO NEXT] FRAT bridge check-in n\xE3o aplicado:", linkErr);
      }
    }
    return c.json(
      {
        success: true,
        data: {
          id: avaliacaoId,
          score_total: scored.totalScore,
          raw_score: scored.rawScore,
          context_rules: scored.contextRules,
          nivel_risco: scored.level,
          exige_aprovacao: Boolean(exigeAprovacao),
          despacho_bloqueado: Boolean(exigeAprovacao)
        }
      },
      201
    );
  } catch (error4) {
    console.error("[SGSO NEXT] Erro ao criar avalia\xE7\xE3o FRAT:", error4);
    return c.json(
      { success: false, error: "Erro ao criar avalia\xE7\xE3o FRAT", code: "SGSO_NEXT_ERROR" },
      500
    );
  }
});
