app41.put("/:id", requireRole2("admin", "manager"), async (c) => {
  const db = c.env.DB;
  const empresa_id = getEmpresaId(c);
  const id = parseInt(c.req.param("id"));
  if (isNaN(id)) return badRequest("ID inv\xE1lido");
  const existing = await db.prepare("SELECT * FROM hospedagem WHERE id = ? AND empresa_id = ? AND deleted_at IS NULL").bind(id, empresa_id).first();
  if (!existing) return notFound("Hospedagem n\xE3o encontrada");
  const body = await c.req.json();
  const parsed = HospedagemUpdateSchema.safeParse(body);
  if (!parsed.success) {
    return badRequest(parsed.error.issues.map((i) => i.message).join("; "));
  }
  const d = parsed.data;
  const updates = ["updated_at = datetime('now')"];
  const bindings = [];
  const fields = [
    ["tipo", d.tipo],
    ["local", d.local],
    ["cidade", d.cidade],
    ["estado", d.estado],
    ["data_checkin", d.data_checkin],
    ["data_checkout", d.data_checkout],
    ["numero_quarto", d.numero_quarto],
    ["custo_diaria", d.custo_diaria],
    ["moeda", d.moeda],
    ["escala_id", d.escala_id],
    ["observacoes", d.observacoes]
  ];
  for (const [col, val] of fields) {
    if (val !== void 0) {
      updates.push(`${col} = ?`);
      bindings.push(val ?? null);
    }
  }
  await db.prepare(`UPDATE hospedagem SET ${updates.join(", ")} WHERE id = ?`).bind(...bindings, id).run();
  const updated = await db.prepare("SELECT * FROM hospedagem WHERE id = ?").bind(id).first();
  await registrarAuditoria({
    db,
    tabela: "hospedagem",
    acao: "UPDATE",
    registro_id: String(id),
    dados_anteriores: existing,
    dados_novos: updated
  });
  return c.json({ success: true, message: "Hospedagem atualizada com sucesso" });
});
