async function sincronizarModelosSessaoChecks(db) {
  const erros = [];
  const checksExistentes = await db.prepare(
    `SELECT DISTINCT sa.template_id AS modelo_id, sc.qualificacao_tipo_id
       FROM sessoes_checks sc
       JOIN simulador_agendamentos sa ON sa.id = sc.sessao_id AND sa.deleted_at IS NULL
       WHERE sc.deleted_at IS NULL
         AND sc.qualificacao_tipo_id IS NOT NULL
         AND sa.template_id IS NOT NULL`
  ).all();
  let inseridos = 0;
  const stmts = [];
  for (const row of checksExistentes.results || []) {
    const existe = await db.prepare(
      `SELECT id FROM modelos_sessao_checks
         WHERE modelo_id = ? AND qualificacao_tipo_id = ? AND deleted_at IS NULL`
    ).bind(row.modelo_id, row.qualificacao_tipo_id).first();
    if (!existe) {
      stmts.push(
        db.prepare(
          `INSERT INTO modelos_sessao_checks (modelo_id, qualificacao_tipo_id, created_at, updated_at)
           VALUES (?, ?, datetime('now'), datetime('now'))`
        ).bind(row.modelo_id, row.qualificacao_tipo_id)
      );
      inseridos++;
    }
  }
  if (stmts.length > 0) {
    try {
      for (let i = 0; i < stmts.length; i += 50) {
        await db.batch(stmts.slice(i, i + 50));
      }
    } catch (e) {
      erros.push(`Erro ao inserir modelos_sessao_checks: ${e.message}`);
    }
  }
  return { inseridos, erros };
}
